export function getTopicContent(subject, chapterId, code) {
  return TOPIC_CONTENT[`${subject}/${chapterId}/${code}`] || null;
}

export function allTopicEntries() {
  return Object.entries(TOPIC_CONTENT).map(([key, v]) => ({ key, ...v }));
}

export function topicProgressId(subject, chapterId, code) {
  return `topic:${subject}/${chapterId}/${code}`;
}

export function coverageStats() {
  const entries = allTopicEntries();
  const withViz = entries.filter((e) => e.modules && e.modules.length).length;
  return {
    total: entries.length,
    withVisualization: withViz,
    textOnly: entries.length - withViz,
  };
}
